design.css:
/* Saffron — the Crunchyroll look (docs/theme-references/crunchyroll.md, tmp/parity/saffron/measure.md):
   black, DM Sans, one orange, square corners. Numbers are the reference site's own CSS at 1440×900. */

/* ── Header: the #272727 bar of 16 px #BBB text tiles; hover and the current page turn white on #151515.
   The row is the site's 60 px header; izumi's 32 px window band stays above it, as a browser's own chrome. ── */
:scope { --theme-top-row: 60px; }
[data-slot="nav.top"] { gap: 0 !important; background: #272727 !important; border: 0 !important; }
[data-slot="nav.top"] > [data-part="nav.item"] { height: 60px; padding: 0 16px; border-radius: 0 !important; background: transparent; color: #bbb !important; font-size: 16px; font-weight: 400; line-height: 22px; transition: background-color 0.1s cubic-bezier(0, 0, 0.25, 1); }
[data-slot="nav.top"] > a[data-part="nav.item"]:first-of-type { margin-left: 14px; }
[data-slot="nav.top"] > [data-part="nav.item"]:hover, [data-slot="nav.top"] > [data-part="nav.item"][data-active] { background: #151515 !important; color: #fff !important; }
/* Categories ▾: a filled 24 px dropdown caret, tile padding 0 12 0 16. */
[data-slot="nav.top"] > [data-part="nav.item"][data-variant="menu"] { padding: 0 12px 0 16px; }
[data-slot="nav.top"] > [data-part="nav.item"][data-variant="menu"] svg { display: none; }
[data-slot="nav.top"] > [data-part="nav.item"][data-variant="menu"]::after { content: ""; width: 0; height: 0; margin: 0 7px 0 11px; border-top: 5px solid currentColor; border-right: 5px solid transparent; border-left: 5px solid transparent; }
/* Right-hand icons: 52 px tiles with 24 px #BBB glyphs, as the search / watchlist / account tiles. */
[data-slot="nav.top"] > [data-part="nav.action"] { width: 52px !important; height: 60px !important; border-radius: 0 !important; background: transparent !important; color: #bbb !important; }
[data-slot="nav.top"] > [data-part="nav.action"]:hover, [data-slot="nav.top"] > [data-part="nav.action"][data-active] { background: #151515 !important; color: #fff !important; }
[data-slot="nav.top"] > [data-part="nav.action"] svg { width: 24px; height: 24px; }

/* Categories: a #151515 panel — browse links on the left, then GENRES over three columns. */
[data-slot="nav.categories"] { border: 0 !important; border-radius: 0 !important; background: #151515 !important; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6) !important; }
[data-slot="nav.categories"] > div { border-color: #272727 !important; }
[data-part="nav.categories.link"] { display: flex; align-items: center; min-height: 44px; padding: 12px 16px !important; line-height: 20px !important; border-radius: 0 !important; color: #f2f2f2 !important; font-size: 16px !important; }
[data-part="nav.categories.link"][data-variant="genre"] { width: 200px !important; color: #bbb !important; font-size: 14px !important; }
[data-part="nav.categories.link"]:hover { background: #272727 !important; color: #fff !important; }
[data-part="nav.categories.heading"] { padding: 13px 16px !important; color: #8c8c8c !important; font-size: 12px !important; font-weight: 700 !important; letter-spacing: -0.36px !important; text-transform: uppercase; }

/* ── Home hero (hero-container + hero-content-card): 16:9 key art that fades to black at the bottom and from
   the left. The copy sits in a 20:7 box (500 px min, up to 100vh − min(350 px, 40vh)); the slide markers
   56 px under it, the rows 72 px under it, the art running on under the first row. ── */
[data-part="saffron.hero"]::after {
  background: linear-gradient(rgba(0, 0, 0, 0) 50%, #000 100%), linear-gradient(to right, rgba(0, 0, 0, 0.85) 0, rgba(0, 0, 0, 0.5) 30%, rgba(0, 0, 0, 0) 55%) !important;
}
/* --saffron-under is the art below the box; the rows start 72 px (markers) + the feed's row gap (48 px,
   96 px from 1440) below the box, which izumi's bleed (rows pulled up by bleed − 24 px) has to equal. */
@media (min-width: 641px) {
  [data-slot="home.hero"][data-variant="template"] { --saffron-box: clamp(300px, 35vw, calc(100vh - 300px)); --saffron-under: calc(56.25vw - var(--saffron-box)); --hero-bleed: calc(var(--saffron-under) - 96px) !important; }
  [data-part="saffron.info"] { padding-bottom: var(--saffron-under) !important; }
  [data-slot="home.hero"] [data-part="hero.indicator"] { bottom: calc(var(--saffron-under) - 64px) !important; }
  [data-slot="home.hero"] [data-part="hero.edge"] { top: calc((var(--saffron-box) + 72px) / 2) !important; }
}
@media (min-width: 1024px) {
  [data-slot="home.hero"][data-variant="template"] { --saffron-box: clamp(360px, 35vw, calc(100vh - 300px)); }
  /* The copy column is four of the twelve 30 px-gutter columns inside the 64 px gutters. */
  [data-part="saffron.info"] { width: calc((100% - 458px) / 3 + 218px) !important; }
}
@media (min-width: 1440px) {
  [data-slot="home.hero"][data-variant="template"] { --saffron-box: clamp(500px, 35vw, calc(100vh - min(350px, 40vh))); --hero-bleed: calc(var(--saffron-under) - 144px) !important; }
}
@media (min-width: 641px) {
  /* The logo box is three columns wide at 15:8, bottom-left aligned. */
  [data-part="saffron.logo"] { width: calc(75% - 7.5px) !important; max-width: none !important; max-height: 320px; aspect-ratio: 15 / 8 !important; }
  [data-part="saffron.synopsis"] { width: 100%; margin-bottom: 32px; line-height: 22px; }
}
[data-part="saffron.logo"] img { object-position: left bottom; }
[data-part="saffron.title"] { margin-bottom: 12px; letter-spacing: -1.02px; line-height: 40px; text-shadow: none !important; }
[data-part="saffron.meta"] { max-height: 20px; margin: 20px 0 8px; overflow: hidden; line-height: 20px; }
[data-part="saffron.age"] { height: 20px; padding: 0 6px; border-radius: 2px; background: #4a4e58; color: #dadada; line-height: 20px; }
/* ◆ separators: a 4 px square turned 45°, 4 px either side, in the line's colour. */
[data-part="saffron.sep"] { width: 4px; height: 4px; margin: 0 4px; background: #8c8c8c; font-size: 0 !important; line-height: 0; transform: rotate(45deg); }
[data-part="saffron.sep"]:first-child { display: none; }
[data-part="saffron.comma"] { margin-right: 4px; }
[data-part="saffron.play"] { height: 40px; padding: 0 16px !important; gap: 4px !important; border-radius: 0 !important; line-height: 20px; text-transform: uppercase; }
[data-part="saffron.play"] svg { width: 24px; height: 24px; fill: none; }
[data-part="saffron.more"] { width: 40px; height: 40px; padding: 0 !important; justify-content: center; border-radius: 0 !important; box-shadow: inset 0 0 0 2px #ff640a; }

/* Slide markers: 24×8 pills at 50% white, the current one 48 wide with the orange loader; 8 px apart. */
[data-slot="home.hero"] [data-part="hero.indicator"] { gap: 8px !important; left: 64px !important; }
[data-part="hero.dot.track"] { width: 24px !important; height: 8px !important; border-radius: 4px !important; background: rgba(255, 255, 255, 0.5) !important; transition: width 0.3s; }
[data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: 48px !important; }
[data-part="hero.dot"]:not([data-active]):hover [data-part="hero.dot.track"] { background: rgba(255, 100, 10, 0.7) !important; }
[data-part="hero.dot.fill"] { border-radius: 4px; }
/* Arrows: bare 46 px white chevrons in 64×100 hit areas at both edges, half-white on hover. */
[data-slot="home.hero"] [data-part="hero.edge"] { height: 100px !important; color: #fff; }
[data-slot="home.hero"] [data-part="hero.edge"] > span { width: 46px !important; height: 46px !important; border: 0 !important; background: transparent !important; box-shadow: none !important; opacity: 1 !important; transform: none !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; }
[data-slot="home.hero"] [data-part="hero.edge"] svg { width: 46px; height: 46px; stroke-width: 2.25; }
[data-slot="home.hero"] [data-part="hero.edge"]:hover { color: rgba(255, 255, 255, 0.5); }

/* ── Rows (feed-header): 28/36 bold headings with −3% tracking, 16 px above the cards; grey VIEW ALL ›. ── */
[data-part="row.title"], [data-part="block.title"] { font-weight: 700; letter-spacing: -0.84px; color: #fff; }
@media (min-width: 641px) { [data-part="row.title"], [data-part="block.title"] { font-size: 28px !important; line-height: 36px; } }
@media (max-width: 640px) { [data-part="row.title"], [data-part="block.title"] { font-size: 22px !important; line-height: 28px; letter-spacing: -0.66px; } }
[data-part="row.header"] { padding-bottom: 8px !important; }
[data-part="row.more"] { flex-shrink: 0; gap: 0 !important; color: #8c8c8c !important; font-size: 14px; font-weight: 700; line-height: 20px; text-transform: uppercase; white-space: nowrap; opacity: 1 !important; }
[data-part="row.more"]:hover { color: #fff !important; }
[data-part="row.more"] svg { width: 24px; height: 24px; margin-left: 6px; }
@media (max-width: 640px) { [data-part="row.more"] { font-size: 12px; } }
/* The page gutter is 64 px on desktop; the carousel clips 12 px past it, so five cards show and none peeks. */
@media (min-width: 1024px) {
  [data-part="row.header"], [data-part="row.track"] { padding-left: 64px !important; padding-right: 64px !important; }
  [data-part="row.track"] { clip-path: inset(0 52px); }
  /* Carousel arrows: bare 40 px #F2F2F2 chevrons in the gutter beside the cards, #272727 behind on hover. */
  [data-part="row.step"] { width: 40px !important; height: 40px !important; border: 0 !important; border-radius: 0 !important; background: transparent !important; box-shadow: none !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; color: #f2f2f2 !important; }
  [data-part="row.step"][data-dir="previous"] { left: 24px !important; }
  [data-part="row.step"][data-dir="next"] { right: 24px !important; left: auto !important; }
  [data-part="row.step"]:hover { background: #272727 !important; color: #fff !important; }
  [data-part="row.step"] svg { width: 40px; height: 40px; stroke-width: 1.5; }
}

/* ── Poster cards (browse-card): square art, the title 12 px under it, the grey line 8 px under that. ── */
[data-part="saffron.poster"] img { transform: none !important; }
[data-part="saffron.card-title"] { margin-top: 12px; letter-spacing: -0.42px; line-height: 20px; }
[data-part="saffron.card-meta"] { margin-top: 8px; line-height: 17.5px; }
/* Hover (browse-card-hover): a #151515 sheet 8 px larger than the card, the art at 5% under it. */
[data-part="saffron.hover"] { padding: 4px !important; gap: 0 !important; background: rgba(21, 21, 21, 0.95); box-shadow: 0 0 0 8px #151515; opacity: 0; transition: opacity 0.15s; }
[data-part="saffron.hover"] > :first-child { margin-bottom: 12px; letter-spacing: -0.42px; line-height: 20px; }
[data-part="saffron.hover"] > :nth-child(2) { margin-bottom: 4px; line-height: 20px; }
[data-part="saffron.hover"] > :nth-child(3) { margin-bottom: 8px; line-height: 20px; }
[data-part="saffron.hover-synopsis"] { line-height: 20px; }
[data-part="saffron.poster"] { overflow: visible !important; }
/* The sheet covers the whole card: the art plus a one-line title and the grey line (12 + 20 + 8 + 18). */
[data-part="saffron.hover"] { align-self: start; height: calc(100% + 58px) !important; }
[data-part="card"]:hover [data-part="saffron.hover"], [data-part="card"]:focus-within [data-part="saffron.hover"] { opacity: 1; z-index: 2; }

/* ── Continue Watching (playable-card): 16:9 still, 4 px orange progress on rgba(0,0,0,.6), the "21m left"
   chip 4 px in from the corner, then the series name and "E1 - Title" 12 px under the still. ── */
[data-part="saffron.cw-bar"] { min-height: 4px !important; height: 4px !important; border-radius: 0 !important; background: rgba(0, 0, 0, 0.6) !important; }
[data-part="saffron.cw-bar"] > span { border-radius: 0 !important; background: #ff640a !important; }
[data-part="saffron.cw-left"], [data-part="saffron.ep-duration"] { margin: 0 4px 4px 0; padding: 3px 5px; background: rgba(0, 0, 0, 0.6); letter-spacing: -0.42px; line-height: 20px; }
[data-part="saffron.cw-left"] { margin-bottom: 8px; }
[data-part="saffron.cw-series"] { margin-top: 12px; padding-bottom: 5px; text-transform: uppercase; letter-spacing: -0.3px; line-height: 16px; }
[data-part="saffron.cw-ep"] { display: block !important; max-height: 44px; margin-top: 4px; overflow: hidden; line-height: 22px; letter-spacing: -0.48px; }
[data-part="saffron.cw-ep"] > * { display: inline !important; }
[data-part="saffron.cw"] { padding-bottom: 36px; }

/* ── Series page (series-hero): key art min(16:9, box + 208 px) high; the copy bottom-aligned in a box of
   clamp(39.6875vw − 288 px, 2:1, 100vh − 400 px); the synopsis 60 px under the buttons over six columns;
   a 2 px #272727 rule under it. ── */
[data-slot="detail"][data-layout="overlay"][data-variant="desktop"] {
  --saffron-g: clamp(calc(39.6875vw - 288px), 50vw, calc(100vh - 400px));
  --saffron-a: min(56.25vw, calc(var(--saffron-g) + 208px));
  min-height: 0 !important; height: var(--saffron-a);
}
/* The site's fade in izumi's two scrims: the top-right and left layers on the side scrim (now full width),
   the bottom one on the bottom scrim beneath it. */
[data-slot="detail"][data-variant="desktop"] [data-part="detail.scrim"][data-dir="bottom"] { background-image: linear-gradient(rgba(0, 0, 0, 0) 45%, #000 85%) !important; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.scrim"][data-dir="left"] { width: 100% !important; background-image: linear-gradient(252deg, rgba(0, 0, 0, 0.55) 5%, rgba(0, 0, 0, 0) 20%), linear-gradient(to right, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.5) 30%, rgba(0, 0, 0, 0) 55%) !important; }
[data-slot="detail"][data-layout="overlay"][data-variant="desktop"]::before {
  content: ""; position: absolute; z-index: 2; top: calc(var(--saffron-g) + 196px); right: 64px; left: 64px; height: 2px; background: #272727;
}
[data-slot="detail"][data-layout="overlay"] [data-part="detail.backdrop"] { object-position: right top !important; }
[data-slot="detail"][data-layout="overlay"][data-variant="desktop"] [data-part="detail.body"] {
  min-height: 0 !important; height: 100%; max-width: none !important; justify-content: flex-end !important; gap: 0 !important;
  padding: 0 64px calc(var(--saffron-a) - var(--saffron-g)) !important;
}
[data-slot="detail"][data-layout="overlay"][data-variant="desktop"] [data-part="detail.body"] > * { max-width: calc((100vw - 458px) * 5 / 12 + 120px); }
[data-slot="detail"][data-layout="overlay"] [data-part="detail.alt-title"],
[data-slot="detail"][data-layout="overlay"] [data-part="detail.studio"],
[data-slot="detail"][data-layout="overlay"] [data-part="detail.meta"] { display: none !important; }
[data-slot="detail"][data-layout="overlay"] [data-part="detail.title"] { order: 1; font-size: 34px !important; font-weight: 700 !important; letter-spacing: -1.02px; line-height: 40px !important; text-shadow: none !important; filter: none !important; }
[data-slot="detail"][data-layout="overlay"] [data-part="detail.header"] { order: 2; margin-top: 20px; }
[data-slot="detail"][data-layout="overlay"] [data-part="detail.rating"] { order: 3; margin-top: 12px !important; }
[data-slot="detail"][data-layout="overlay"] [data-part="detail.actions"] { order: 4; margin-top: 32px; gap: 10px !important; }
[data-slot="detail"][data-layout="overlay"][data-variant="desktop"] [data-part="detail.synopsis"] {
  position: absolute; top: calc(var(--saffron-g) + 60px); left: 64px; width: calc((100vw - 458px) / 2 + 150px); max-width: none !important;
  -webkit-line-clamp: 4 !important; color: #fff !important; font-size: 16px !important; line-height: 22px !important;
  -webkit-mask-image: linear-gradient(#000 66px, rgba(0, 0, 0, 0.15) 88px); mask-image: linear-gradient(#000 66px, rgba(0, 0, 0, 0.15) 88px);
}
[data-part="detail.logo"] { max-width: 342px !important; max-height: 182px !important; object-position: left bottom; }
[data-part="saffron.detail-meta"] { max-height: 20px; overflow: hidden; line-height: 20px; }
[data-part="saffron.detail-meta"] [data-part="saffron.sep"] { background: #bbb; }
[data-part="saffron.detail-meta"] [data-part="saffron.genre"] { text-decoration: underline 1px; text-underline-offset: 2px; }
/* ★★★★★ | Average Rating: 8.6 (184K) ▾ — 28 px #BBB stars, a 1×20 #414141 rule 8 px either side. */
[data-part="saffron.stars"]::after { content: ""; width: 1px; height: 20px; margin: 0 8px; background: #414141; }
[data-part="saffron.star"] svg { fill: currentColor; stroke-width: 1; }
[data-part="saffron.avg-label"] { margin-right: 4px; letter-spacing: -0.42px; line-height: 20px; }
[data-part="saffron.avg"], [data-part="saffron.avg-count"] { letter-spacing: -0.42px; line-height: 20px; text-transform: uppercase; }
[data-part="saffron.avg-count"] { margin-left: 4px; }
[data-part="saffron.avg-caret"] { width: 24px; height: 24px; margin-left: 4px; }
[data-part="saffron.avg-caret"] svg { display: none; }
[data-part="saffron.avg-caret"]::after { content: ""; border-top: 5px solid currentColor; border-right: 5px solid transparent; border-left: 5px solid transparent; }
/* START WATCHING E1 (CONTINUE WATCHING E3 once started), the bookmark square with the inset orange ring. */
[data-slot="detail"] [data-part="button"][data-variant="primary"] { height: 40px; padding: 0 16px !important; gap: 4px !important; border-radius: 0 !important; background: #ff640a !important; color: #000 !important; font-size: 0 !important; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] svg { width: 24px; height: 24px; fill: none; }
[data-slot="detail"] [data-part="button"][data-variant="primary"]::after { content: "Start watching E" attr(data-episode); font-size: 14px; font-weight: 700; line-height: 20px; text-transform: uppercase; }
[data-slot="detail"] [data-part="button"][data-variant="primary"][data-state="resume"]::after { content: "Continue watching E" attr(data-episode); }
[data-slot="detail"] [data-part="button"][data-variant="secondary"] { width: 40px !important; height: 40px !important; border-radius: 0 !important; background: transparent !important; box-shadow: inset 0 0 0 2px #ff640a; color: #ff640a !important; }
[data-slot="detail"] [data-part="button"][data-variant="secondary"] svg { width: 24px; height: 24px; }
[data-slot="detail"] [data-part="tab"][data-active] { color: #fff; }
[data-slot="detail"] [data-part="tab"][data-active] > span { background: #ff640a; }

/* ── Episodes (erc-season-with-navigation): the 64 px gutter, the season dropdown and the grey controls in a
   44 px row 12 px above a five-column grid of playable cards with 30 px gutters. ── */
@media (min-width: 641px) {
  [data-slot="detail.episodes"], [data-slot="detail.section"] { padding-left: 32px; padding-right: 32px; }
  [data-slot="detail"][data-layout="overlay"][data-variant="desktop"] ~ div [data-slot="detail.episodes"] { margin-top: 48px; }
  [data-part="episodes.grid"] { grid-template-columns: repeat(5, minmax(0, 1fr)) !important; gap: 30px !important; }
}
[data-part="saffron.ep-art"] img { transform: none !important; }
[data-slot="detail.episodes"] [data-part="episode"][data-variant="template"] { border-radius: 0 !important; background: transparent !important; }
[data-slot="detail.episodes"] [data-part="episode"][data-variant="template"]:hover [data-part="saffron.cw-ep"] { color: #fff; text-decoration: underline; text-underline-offset: 3px; }
[data-part="saffron.ep"] { padding-bottom: 36px; }
[data-slot="episodes.toolbar"] { min-height: 44px; margin-bottom: 12px !important; column-gap: 0 !important; }
[data-part="episodes.heading"] { font-size: 18px !important; font-weight: 700 !important; letter-spacing: -0.54px; line-height: 24px; }
[data-part="episodes.count"] { color: #8c8c8c !important; }
[data-part="episodes.sort"], [data-part="episodes.more"] { display: inline-flex !important; align-items: center; height: 44px !important; width: auto !important; gap: 8px; padding: 10px 12px 10px 8px !important; border-radius: 0 !important; background: transparent !important; box-shadow: none !important; color: #8c8c8c !important; font-size: 14px !important; font-weight: 700 !important; line-height: 20px; text-transform: uppercase; }
[data-part="episodes.sort"] svg, [data-part="episodes.more"] svg { width: 24px; height: 24px; }
[data-part="episodes.sort"]:hover, [data-part="episodes.more"]:hover { color: #fff !important; }
[data-part="episodes.more"]::after { content: "Options"; }
[data-part="episodes.menu"] { border: 0 !important; border-radius: 0 !important; background: #23252b !important; }
/* The season dropdown: a filled caret, 5 px, then the 18/24 bold season name. */
[data-part="season.toggle"] { height: 44px; gap: 5px !important; padding: 10px 8px 10px 0 !important; font-size: 18px !important; font-weight: 700 !important; letter-spacing: -0.54px; line-height: 24px; }
[data-part="season.toggle"] svg { display: none; }
[data-part="season.toggle"]::before { content: ""; flex: none; width: 0; height: 0; margin: 0 7px; border-top: 5px solid currentColor; border-right: 5px solid transparent; border-left: 5px solid transparent; }

/* Below the episodes: More like this, related titles, cast and details, 60 px apart under 20/26 headings. */
[data-slot="detail.section"] { margin-top: 60px !important; }
[data-part="detail.section-title"] { margin: 0 0 24px !important; color: #fff; font-size: 20px !important; font-weight: 700 !important; line-height: 26px; letter-spacing: -0.6px; }
@media (min-width: 641px) {
  [data-slot="detail.recommended"], [data-slot="detail.relations"] { display: grid !important; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 30px !important; }
  [data-slot="detail.recommended"] > *, [data-slot="detail.relations"] > *, [data-part="relation"] > div { width: auto !important; min-width: 0; }
}

/* ── Search (search-field + browse grid): a #151515 band with the 34 px field over a 2 px orange rule,
   880 px wide and centred; the results six 150 px posters a row with 30 px gutters in a 1050 px column. ── */
@media (min-width: 641px) {
  [data-slot="search"] { padding-top: 32px !important; }
  [data-part="search.filters"] { flex-wrap: wrap !important; row-gap: 56px !important; max-width: 1050px; margin: 0 auto; }
  [data-part="search.field"] {
    flex: 0 0 min(880px, 100%) !important; height: 50px !important; margin: 0 calc((100% - min(880px, 100%)) / 2) !important; padding: 2px 4px !important;
    border: 0 !important; border-bottom: 2px solid #ff640a !important; border-radius: 0 !important; background: #151515 !important;
