/* ── Phone (≤ 640 px): the 60 px #272727 bar, 20 px gutters, 22/28 headings 12 px above the cards. ── */
@media (max-width: 640px) {
  [data-slot="home.header"] { display: grid; align-content: center; box-sizing: border-box; min-height: 60px; padding-top: 0 !important; padding-bottom: 0 !important; background: #272727 !important; }
