  [data-part="saffron.logo"] { width: calc((100% - 110px) / 2 + 50px) !important; max-width: none !important; aspect-ratio: 15 / 8 !important; }
  [data-part="saffron.logo"] img { object-position: center bottom; }
  [data-part="saffron.title"] { line-height: 30px; letter-spacing: -0.72px; }
  [data-part="saffron.meta"] { justify-content: center; margin: 12px 0 20px; }
}

/* ── Phone series page (series-container, 2:3 art): the copy centred from 75% of the width down, then a
   full-width orange button; the synopsis on black; episodes as 151×85 rows 12 px apart. ── */
[data-slot="detail"][data-layout="overlay"] [data-part="detail.synopsis"] { order: 5; }
@media (max-width: 640px) {
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] { height: auto !important; min-height: 0 !important; overflow: visible !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.backdrop"], [data-slot="detail"][data-variant="phone"] [data-part="detail.banner.fade"] { bottom: auto !important; height: 150vw !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.banner.fade"] { background: linear-gradient(204deg, rgba(0, 0, 0, 0.6) 0%, rgba(0, 0, 0, 0) 20%), linear-gradient(rgba(0, 0, 0, 0) 40%, rgba(0, 0, 0, 0.75) 65%, #000 90%) !important; }
  [data-slot="detail"][data-layout="overlay"][data-variant="phone"] [data-part="detail.body"] { min-height: 0 !important; justify-content: flex-start !important; align-items: center !important; gap: 0 !important; padding: 75vw 20px 0 !important; }
