  [data-slot="detail"][data-variant="phone"] [data-part="saffron.detail-meta"], [data-slot="detail"][data-variant="phone"] [data-part="saffron.detail-rating"] { justify-content: center; }
  [data-slot="detail"][data-variant="phone"] [data-part="saffron.detail-meta"] { max-height: 40px; }
  [data-slot="detail"][data-variant="phone"] [data-part="saffron.avg-label"] { display: none; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.body"] > [data-part="button"][data-variant="primary"] { order: 4; width: 100% !important; margin-top: 20px; justify-content: center; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.synopsis"] { align-self: stretch; margin-top: 40px; color: #fff !important; font-size: 14px !important; line-height: 20px !important; text-align: left; }
  [data-slot="detail.episodes"] [data-part="saffron.ep"] { display: flow-root !important; height: 85px; padding: 0 !important; }
  [data-slot="detail.episodes"] [data-part="saffron.ep-art"] { float: left; width: 151px; height: 85px; margin-right: 12px; }
  [data-slot="detail.episodes"] [data-part="saffron.cw-ep"] { max-height: 40px; line-height: 20px; }
  [data-slot="detail.episodes"] [data-part="saffron.cw-ep"] * { font-size: 14px !important; }
  [data-part="episodes.grid"] { gap: 12px !important; }
}
